"""Sum of All Subset XOR Totals — every bit appears in exactly half the subsets.

So the answer is OR(nums) << (n - 1), no enumeration required.

Time: O(n)   Space: O(1)
"""
from functools import reduce
from operator import or_
from typing import List


class Solution:
    def subsetXORSum(self, nums: List[int]) -> int:
        return reduce(or_, nums) << (len(nums) - 1)
